arguments.command:
cd /app && python3 - <<'EOF'
import json
print(json.loads('{"a":1}  \n '))
try:
    json.loads('{"a":1} x')
except ValueError as e:
    print("extra:", e)
def hook(pairs):
    d={}
    for k,v in pairs:
        if k in d: raise ValueError("dup")
        d[k]=v
    return d
try:
    print(json.loads('{"a":1,"a":2}', object_pairs_hook=hook))
except ValueError as e:
    print("dup:", e)
try:
    print(json.loads('{"a":NaN}', parse_constant=lambda c:(_ for _ in ()).throw(ValueError("nf"))))
except ValueError as e:
    print("nf:", e)
print(json.loads('1e400', parse_float=float))
try:
    json.loads('['*2000 + ']'*2000)
except RecursionError as e:
    print("recursion caught")
EOF
